{"refs":["jobs"],"code":"def solve(facts):
    jobs = facts['jobs']
    n = len(jobs)
    positions = {j['id']: i for i, j in enumerate(jobs)}
    requirements = [sum(1 << positions[p] for p in set(j['predecessors'])) for j in jobs]
    dp = [{} for _ in range(1 << n)]
    dp[0][0] = (0, (), ())
    for mask in range(1 << n):
        for finish, label in dp[mask].items():
            cost, order, starts = label
            for i, job in enumerate(jobs):
                bit = 1 << i
                if mask & bit or requirements[i] & mask != requirements[i]:
                    continue
                start = max(finish, job['release'])
                end = start + job['duration']
                candidate = (cost + job['weight'] * max(0, end - job['due']), order + (job['id'],), starts + (start,))
                target = dp[mask | bit]
                if end not in target or candidate[:2] < target[end][:2]:
                    target[end] = candidate
    if not dp[-1]:
        raise ValueError('No feasible order')
    finish, label = min(dp[-1].items(), key=lambda item: (item[1][0], item[0], item[1][1]))
    return {'order': list(label[1]), 'starts': list(label[2]), 'finish': finish, 'weighted_tardiness': label[0]}


def check(answer, facts):
    jobs = facts['jobs']
    best = None
    best_starts = None

    def visit(remaining, completed, time, cost, order, starts):
        nonlocal best, best_starts
        if not remaining:
            key = (cost, time, tuple(order))
            if best is None or key < best:
                best = key
                best_starts = list(starts)
            return
        for index, job in enumerate(remaining):
            if not all(p in completed for p in job['predecessors']):
                continue
            start = time if time >= job['release'] else job['release']
            finish = start + job['duration']
            lateness = finish - job['due']
            penalty = job['weight'] * lateness if lateness > 0 else 0
            visit(remaining[:index] + remaining[index + 1:], completed | {job['id']}, finish, cost + penalty, order + [job['id']], starts + [start])

    visit(list(jobs), set(), 0, 0, [], [])
    if best is None or not isinstance(answer, dict):
        return False
    expected = {'order': list(best[2]), 'starts': best_starts, 'finish': best[1], 'weighted_tardiness': best[0]}
    return answer == expected
"}

